<?php
namespace App\Http\Controllers;
use App\Models\{User, Department, ExpenseCategory};
use App\Services\{InventoryService, FinanceService};
use App\Support\{Audit, Money};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Inertia\Inertia;
class InventoryController extends Controller
{
    private function save(string $table, array $data): int { return DB::table($table)->insertGetId($data + ['created_at' => now(), 'updated_at' => now()]); }
    public function index(Request $r) {
        $items = DB::table('stock_items')->join('inventory_categories', 'inventory_categories.id', '=', 'category_id')->join('inventory_locations', 'inventory_locations.id', '=', 'location_id')->select('stock_items.*', 'inventory_categories.name as category', 'inventory_locations.name as location')->when($r->filled('search'), fn ($q) => $q->where(fn ($q) => $q->where('stock_items.name', 'like', '%'.$r->input('search').'%')->orWhere('code', 'like', '%'.$r->input('search').'%')))->get();
        return Inertia::render('Inventory/Index', ['items' => $items, 'lowStock' => $items->filter(fn ($item) => bccomp((string) $item->quantity, (string) $item->threshold, 3) <= 0)->values(), 'movements' => DB::table('stock_movements')->join('stock_items', 'stock_items.id', '=', 'stock_item_id')->select('stock_movements.*', 'stock_items.name')->latest('stock_movements.id')->paginate(25),
            'categories' => DB::table('inventory_categories')->get(), 'locations' => DB::table('inventory_locations')->get(), 'suppliers' => DB::table('suppliers')->get(), 'purchases' => DB::table('purchase_requests')->join('stock_items', 'stock_items.id', '=', 'stock_item_id')->join('suppliers', 'suppliers.id', '=', 'supplier_id')->select('purchase_requests.*', 'stock_items.name as item', 'suppliers.name as supplier')->latest('purchase_requests.id')->get(),
            'assets' => DB::table('fixed_assets')->join('inventory_locations', 'inventory_locations.id', '=', 'location_id')->leftJoin('users', 'users.id', '=', 'assigned_to')->select('fixed_assets.*', 'inventory_locations.name as location', 'users.name as assigned_staff')->get(), 'assetEvents' => DB::table('asset_events')->latest('id')->paginate(20, ['*'], 'asset_events_page'), 'staff' => User::get(['id', 'name']), 'departments' => Department::get(['id', 'name']), 'filters' => $r->only('search')]);
    }
    public function category(Request $r) { $data = $r->validate(['name' => ['required', 'string', 'max:100', 'unique:inventory_categories,name'], 'type' => ['required', 'in:consumable,asset']]); $this->save('inventory_categories', $data); return back()->with('success', 'Inventory category saved.'); }
    public function location(Request $r) { $data = $r->validate(['name' => ['required', 'string', 'max:100', 'unique:inventory_locations,name']]); $this->save('inventory_locations', $data); return back()->with('success', 'Location saved.'); }
    public function supplier(Request $r) { $data = $r->validate(['name' => ['required', 'string', 'max:150'], 'phone' => ['nullable', 'string', 'max:40'], 'email' => ['nullable', 'email', 'max:200'], 'address' => ['nullable', 'string', 'max:500']]); $this->save('suppliers', $data); return back()->with('success', 'Supplier saved.'); }
    public function item(Request $r) { $data = $r->validate(['category_id' => ['required', 'exists:inventory_categories,id'], 'location_id' => ['required', 'exists:inventory_locations,id'], 'code' => ['required', 'alpha_dash', 'max:50', 'unique:stock_items,code'], 'name' => ['required', 'string', 'max:150'], 'unit' => ['required', 'string', 'max:30'], 'threshold' => ['required', 'numeric', 'between:0,99999999999']]); abort_unless(DB::table('inventory_categories')->where('id', $data['category_id'])->where('type', 'consumable')->exists(), 422, 'Use a consumable category for stock items.'); $this->save('stock_items', $data); return back()->with('success', 'Consumable item saved. Use an audited movement to add opening stock.'); }
    public function movement(Request $r, InventoryService $service) { $data = $r->validate(['stock_item_id' => ['required', 'exists:stock_items,id'], 'type' => ['required', 'in:opening,receipt,issue,return,damage,adjustment'], 'quantity' => ['required', 'numeric'], 'reason' => ['required', 'string', 'max:1000']]); $service->move($data['stock_item_id'], $data['type'], (string) $data['quantity'], $data['reason'], $r->user()); return back()->with('success', 'Stock movement recorded.'); }
    public function itemSettings(Request $r, int $item) { $data = $r->validate(['threshold' => ['required', 'numeric', 'between:0,99999999999'], 'location_id' => ['required', 'exists:inventory_locations,id'], 'reason' => ['required', 'string', 'max:1000']]); $old = DB::table('stock_items')->find($item); abort_unless($old, 404); DB::table('stock_items')->where('id', $item)->update(['threshold' => $data['threshold'], 'location_id' => $data['location_id'], 'updated_at' => now()]); Audit::record('stock_settings_updated', null, ['item_id' => $item, 'threshold' => $old->threshold, 'location_id' => $old->location_id], $data, $data['reason'], 'Stock threshold or location changed'); return back()->with('success', 'Stock settings updated.'); }
    public function purchase(Request $r) { $data = $r->validate(['stock_item_id' => ['required', 'exists:stock_items,id'], 'supplier_id' => ['required', 'exists:suppliers,id'], 'quantity' => ['required', 'numeric', 'gt:0'], 'total' => ['required', 'numeric', 'gt:0'], 'reason' => ['required', 'string', 'max:1000']]); $total = Money::fromMajor($data['total']); unset($data['total']); $this->save('purchase_requests', $data + ['total_minor' => $total, 'requested_by' => $r->user()->id]); Audit::record('purchase_requested', null, [], ['item_id' => $data['stock_item_id']], $data['reason'], 'Inventory purchase requested'); return back()->with('success', 'Purchase request submitted for approval.'); }
    public function purchaseStage(Request $r, int $purchase, InventoryService $service) { $data = $r->validate(['status' => ['required', 'in:approved,ordered,received']]); abort_unless($r->user()->can($data['status'] === 'approved' ? 'purchases.approve' : 'inventory.manage'), 403); if ($data['status'] === 'received') $service->receive($purchase, $r->user()); else DB::transaction(function () use ($purchase, $data, $r) { $row = DB::table('purchase_requests')->where('id', $purchase)->lockForUpdate()->first(); abort_unless($row && $row->status === ($data['status'] === 'approved' ? 'requested' : 'approved'), 422, 'Invalid purchasing stage.'); DB::table('purchase_requests')->where('id', $purchase)->update(['status' => $data['status'], 'approved_by' => $data['status'] === 'approved' ? $r->user()->id : $row->approved_by, 'order_no' => $data['status'] === 'ordered' ? 'TSS-PO-'.str_pad((string) $purchase, 6, '0', STR_PAD_LEFT) : $row->order_no, 'updated_at' => now()]); Audit::record('purchase_stage_changed', null, ['status' => $row->status], ['id' => $purchase, 'status' => $data['status']], null, 'Purchase approval or order recorded'); }); return back()->with('success', 'Purchasing stage updated.'); }
    public function asset(Request $r) { $data = $r->validate(['code' => ['required', 'alpha_dash', 'max:50', 'unique:fixed_assets,code'], 'description' => ['required', 'string', 'max:250'], 'category_id' => ['required', 'exists:inventory_categories,id'], 'location_id' => ['required', 'exists:inventory_locations,id'], 'purchase' => ['required', 'numeric', 'min:0'], 'purchase_date' => ['required', 'date'], 'condition' => ['required', 'string', 'max:50'], 'assigned_to' => ['nullable', 'exists:users,id'], 'department_id' => ['nullable', 'exists:departments,id']]); abort_unless(DB::table('inventory_categories')->where('id', $data['category_id'])->where('type', 'asset')->exists(), 422, 'Use an asset category for fixed assets.'); $value = Money::fromMajor($data['purchase']); unset($data['purchase']); $this->save('fixed_assets', $data + ['purchase_minor' => $value]); Audit::record('asset_registered', null, [], ['code' => $data['code']], null, 'Fixed asset registered separately from stock'); return back()->with('success', 'Asset registered. Values are original purchase cost; no unconfirmed depreciation policy is applied.'); }
    public function assetEvent(Request $r, int $asset, FinanceService $finance) { $data = $r->validate(['type' => ['required', 'in:transfer,maintenance,repair,disposal'], 'location_id' => ['nullable', 'exists:inventory_locations,id'], 'assigned_to' => ['nullable', 'exists:users,id'], 'condition' => ['nullable', 'string', 'max:50'], 'reason' => ['required', 'string', 'max:2000'], 'cost' => ['nullable', 'numeric', 'min:0']]); if ($data['type'] === 'disposal') abort_unless($r->user()->can('assets.dispose'), 403); DB::transaction(function () use ($data, $asset, $r, $finance) { $row = DB::table('fixed_assets')->where('id', $asset)->lockForUpdate()->first(); abort_unless($row && $row->status !== 'disposed', 422, 'Disposed assets cannot be changed.'); $cost = Money::fromMajor($data['cost'] ?? '0'); unset($data['cost']); $expense = $cost > 0 ? $finance->recordExpense(['expense_category_id' => ExpenseCategory::firstOrCreate(['name' => 'Asset maintenance'])->id, 'expense_date' => today()->toDateString(), 'payee' => 'Asset '.$row->code, 'description' => $data['reason'], 'amount_minor' => $cost, 'payment_method' => 'bank_transfer'], $r->user()) : null; $this->save('asset_events', $data + ['fixed_asset_id' => $asset, 'cost_minor' => $cost, 'expense_id' => $expense?->id, 'user_id' => $r->user()->id]); $changes = ['updated_at' => now()]; if ($data['type'] === 'disposal') $changes['status'] = 'disposed'; if (! empty($data['location_id'])) $changes['location_id'] = $data['location_id']; if (array_key_exists('assigned_to', $data)) $changes['assigned_to'] = $data['assigned_to']; if (! empty($data['condition'])) $changes['condition'] = $data['condition']; DB::table('fixed_assets')->where('id', $asset)->update($changes); Audit::record('asset_event_recorded', null, [], ['asset_id' => $asset, 'type' => $data['type']], $data['reason'], 'Asset transfer, maintenance or disposal recorded'); }); return back()->with('success', 'Asset event recorded with history preserved. Any cost awaits normal expense approval.'); }
}

